#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int D, N, M;
    while (scanf("%d", &D), D) {  // Combined the input check into the while condition
        scanf("%d %d", &N, &M);

        vector<int> S(N + 1);
        vector<int> T(M);
        S[0] = 0;
        S[N] = D;

        for (int i = 1; i < N; i++) { scanf("%d", &S[i]); }
        for (int i = 0; i < M; i++) { scanf("%d", &T[i]); }

        sort(S.begin(), S.end());

        long long distance_ = 0;
        for (int i = 0; i < M; i++) {
            int l = *(upper_bound(S.begin(), S.end(), T[i]) - 1);
            int r = *lower_bound(S.begin(), S.end(), T[i]);
            distance_ += min(T[i] - l, r - T[i]);
        }

        printf("%lld\n", distance_);
    }
    return 0;
}

