#include <cstdio>
#include <algorithm>
using namespace std;

const int MAXN = 100005;
int S[MAXN], T[MAXN];

int main() {
    int D, N, M;
    while (true) {
        if (scanf("%d", &D) != 1 || D == 0) { break; }
        scanf("%d %d", &N, &M);

        S[0] = 0;
        S[N] = D;

        for (int i = 1; i < N; i++) { 
            scanf("%d", &S[i]); 
        }
        for (int i = 0; i < M; i++) { 
            scanf("%d", &T[i]); 
        }

        // Sort S array
        sort(S, S + N + 1);

        long long distance_ = 0;
        for (int i = 0; i < M; i++) {
            int ti = T[i];
            // Manual binary search to find l and r
            int l = 0, r = N;
            while (l < r) {
                int mid = (l + r) / 2;
                if (S[mid] < ti) {
                    l = mid + 1;
                } else {
                    r = mid;
                }
            }
            int left = (l > 0) ? S[l - 1] : S[0];
            int right = (l < N + 1) ? S[l] : S[N];

            distance_ += min(ti - left, right - ti);
        }

        printf("%lld\n", distance_);
    }
    return 0;
}

