#include <cstdio>
#include <vector>
#include <algorithm>
#include <thread>
#include <future>
using namespace std;

long long calculate_distance(const vector<int>& S, const vector<int>& T, int start, int end) {
    long long distance_ = 0;
    for (int i = start; i < end; i++) {
        int l = *(upper_bound(S.begin(), S.end(), T[i]) - 1);
        int r = *lower_bound(S.begin(), S.end(), T[i]);
        distance_ += min(T[i] - l, r - T[i]);
    }
    return distance_;
}

int main() {
    int D, N, M;
    while (true) {
        scanf("%d", &D);
        if (D == 0) { break; }
        scanf("%d %d", &N, &M);

        vector<int> S(N + 1);
        vector<int> T(M);
        S[0] = 0;
        S[N] = D;

        for (int i = 1; i < N; i++) { scanf("%d", &S[i]); }
        for (int i = 0; i < M; i++) { scanf("%d", &T[i]); }

        sort(S.begin(), S.end());

        auto f1 = async(launch::async, calculate_distance, ref(S), ref(T), 0, M / 2);
        auto f2 = async(launch::async, calculate_distance, ref(S), ref(T), M / 2, M);
        long long distance_ = f1.get() + f2.get();

        printf("%lld\n", distance_);
    }
    return 0;
}

